package com.chlna.tongshihanzi.domain.search;import static org.junit.Assert.*;import org.junit.Test;public class PinyinNormalizerTest{@Test public void normalizesToneMarksAndNumbers(){assertEquals("xing",PinyinNormalizer.normalize("xíng"));assertEquals("xing",PinyinNormalizer.normalize("xing2"));assertEquals("lv",PinyinNormalizer.normalize("lǜ"));}@Test public void extractsTone(){assertEquals(2,PinyinNormalizer.extractTone("xíng"));assertEquals(4,PinyinNormalizer.extractTone("xing4"));}}
